WITH filtered_web_events AS (SELECT * FROM web_events WHERE duration_sec = 311 AND page = '/checkout'), web_events_stats AS (SELECT session_id, page, SORT_ARRAY(COLLECT_SET(page)) AS page_list, COUNT(DISTINCT duration_sec) AS unique_event_types FROM filtered_web_events GROUP BY session_id, page) SELECT session_id, page, page_list FROM web_events_stats WHERE unique_event_types >= 9;
